from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
checks = []

def check(label, condition):
    checks.append((label, bool(condition)))

geom_lib = (ROOT / "source/cadcraft/crates/geom/src/lib.rs").read_text()
brep = (ROOT / "source/cadcraft/crates/geom/src/brep.rs").read_text()
brep_tests = (ROOT / "source/cadcraft/crates/geom/src/brep.rs").read_text()
file_cmd = (ROOT / "source/cadcraft/crates/engine/src/cmd/file.rs").read_text()
loss_tests = (ROOT / "source/cadcraft/crates/engine/tests/save_reports_not_saved.rs").read_text()
ui_save_loss = (ROOT / "source/cadcraft/crates/ui-egui/src/save_loss.rs").read_text()
ui_loss_tests = (ROOT / "source/cadcraft/crates/ui-egui/tests/save_loss.rs").read_text()
solid3d = (ROOT / "source/cadcraft/crates/engine/src/cmd/draw2/solid3d.rs").read_text()
draw2 = (ROOT / "source/cadcraft/crates/engine/src/cmd/draw2.rs").read_text()
io_lib = (ROOT / "source/cadcraft/crates/io/src/lib.rs").read_text()
io_tests = (ROOT / "source/cadcraft/crates/io/src/tests.rs").read_text()

check("3D kernel foundation is exported from the geometry crate", "pub mod brep;" in geom_lib and "pub use brep::{" in geom_lib)
check("B-rep has explicit vertices, edges, half-edges, loops, faces, shells and solids", all(x in brep for x in ["pub struct BrepEdge", "pub struct BrepHalfEdge", "pub struct BrepLoop", "pub struct BrepFace", "pub struct BrepShell", "pub struct BrepSolid"]))
check("B-rep validation checks reciprocal twins and closed loop adjacency", "a.twin != e.half_edges[1]" in brep and "next.prev != i" in brep and "visited < 3" in brep)
check("First 3D operation creates a validated faceted polygon extrusion (not an editable B-rep solid)", "pub fn extrude_polygon" in brep and "OpenOrNonManifoldEdge" in brep)
check("3D mass and area properties are exposed", "pub fn volume(&self)" in brep and "pub fn surface_area(&self)" in brep)
check("3D regression coverage includes positive, negative, tiny and invalid profiles", all(x in brep_tests for x in ["extrudes_a_square", "negative_extrusion", "microscopic_profiles", "bow_tie"]))
check("DWG loss report includes entity reactors and colour-book metadata", "ENTITY_REACTORS" in file_cmd and "ENTITY_COLOR_BOOK_NAMES" in file_cmd)
check("DWG loss report includes table/block XDATA, reactors and colour-book metadata", all(x in file_cmd for x in ["TABLE_OR_BLOCK_XDATA", "TABLE_OR_BLOCK_REACTORS", "TABLE_OR_BLOCK_COLOR_BOOK_NAMES"]))
check("DWG loss report identifies retained custom-class objects", "CUSTOM_CLASS_OBJECT:" in file_cmd and "foreign.classes" in file_cmd)
check("DWG loss metadata has an engine regression test", "dwg_loss_report_includes_foreign_metadata_the_bridge_drops" in loss_tests)
check("Pre-save dialog explicitly covers objects and metadata", "objects or metadata" in ui_save_loss)
check("Metadata-only DWG loss is held and cancellation preserves source", "metadata_only_dwg_loss_is_blocked_until_the_user_answers" in ui_loss_tests and "metadata is not discarded before consent" in ui_loss_tests)
check("DWG I/O layer refuses unsupported entities and bridge-loss metadata", "dwg_write_blockers" in io_lib and "DWG export blocked to prevent silent data loss" in io_lib)
check("DWG preflight covers partial reads and unsupported entity payloads", all(x in io_lib for x in ["DWG_READ_NOTES", "SKIPPED_DXF_RECORDS", "UNSUPPORTED_ENTITY:"]))
check("DWG preflight has direct regression tests for unsupported entities, metadata and incomplete reads", all(x in io_tests for x in ["dwg_export_refuses_unmodelled_entities", "dwg_export_refuses_known_metadata_loss", "dwg_export_refuses_a_partial_or_damaged_source_read"]))
check("DXF export refuses parser-reported partial reads", "DXF export blocked because the source read was incomplete" in io_lib and "dxf_export_refuses_a_partial_source_read" in io_tests)
check("Lossy DWG overwrite cannot be accepted from the UI", "SaveAnyway" not in ui_save_loss and "lossy DWG overwrite is disabled" in ui_save_loss)
check("3D EXTRUDE command is registered in the Draw command set", "mod solid3d;" in draw2 and "v.extend(solid3d::specs())" in draw2 and "CommandSpec::new(\"extrude\"" in solid3d)
check("EXTRUDE accepts closed lightweight polylines or explicit polygon points", "profile_from_entity" in solid3d and "profile_from_points" in solid3d and "poly.closed" in solid3d)
check("EXTRUDE has a document-handle integration regression test", "extrude_accepts_closed_polyline_handle" in solid3d and "handle.hex()" in solid3d)
check("EXTRUDE validates B-rep before emitting native 3DFACE entities", "brep.validate()" in solid3d and "EntityKind::Face3d" in solid3d)
check("EXTRUDE triangulates concave caps and has geometry regression tests", "triangulate_cap" in solid3d and "extrude_concave_profile_triangulates_caps" in solid3d)
check("EXTRUDE validates the emitted faceted shell before mutating the drawing", "validate_closed_face_mesh(&faces_to_add)?" in solid3d and "open or inconsistently oriented" in solid3d)
check("EXTRUDE regression tests reject missing faces and verify concave cap seams", "faceted_shell_validator_rejects_a_missing_face" in solid3d and "concave_extrusion_shell_has_no_open_triangulation_seams" in solid3d)
check("EXTRUDE persists a shared XDATA group identity on every generated face", "SOLID_XDATA_APP" in solid3d and "entity.common.xdata.extend" in solid3d and "mesh_face_count as i32" in solid3d)
check("SOLIDINFO command discovers and validates a complete grouped shell", 'CommandSpec::new("solidinfo"' in solid3d and "run_solid_info" in solid3d and "validate_closed_face_mesh(&faces)" in solid3d)
check("SOLIDDELETE command removes the complete group and refuses incomplete groups", 'CommandSpec::new("solideditdelete"' in solid3d and "run_solid_delete" in solid3d and "refusing partial deletion" in solid3d)
check("3D group persistence and inspection have regression tests", "extrusion_faces_keep_persistent_group_metadata_and_can_be_inspected" in solid3d)
check("3D group deletion has complete and incomplete group regression tests", "grouped_extrusion_delete_removes_all_faces_atomically" in solid3d and "grouped_extrusion_delete_refuses_incomplete_group" in solid3d)
check("3D group validation checks unique contiguous face indices and blocks corrupt deletes", "fn group_members" in solid3d and "indices.insert(index as usize)" in solid3d and "metadata_valid" in solid3d and "grouped_extrusion_info_rejects_duplicate_face_indices" in solid3d)
check("3D group XDATA parser rejects duplicate or malformed metadata fields", "let mut malformed = false" in solid3d and "if malformed || version != Some(SOLID_XDATA_VERSION)" in solid3d)
check("EXTRUDE runtime regression expects the exact emitted representation label", 'assert_eq!(result["representation"], "grouped-faceted-3dface-shell")' in solid3d)
check("B-rep face loops are uniquely owned by one face", "let mut face_loop_seen" in brep and "face_loop_seen.iter().any(|seen| !seen)" in brep)
overkill = (ROOT / "source/cadcraft/crates/engine/src/cmd/overkill.rs").read_text()
overkill_tests = (ROOT / "source/cadcraft/crates/engine/tests/it/overkill.rs").read_text()
check("OVERKILL merges redundant straight vertices across closed-polyline seam", "cyclic" in overkill and "while pl.closed && pl.vertices.len() > min" in overkill and "closed_polyline_collinear_run_across_closing_edge_is_merged" in overkill_tests)
check("OVERKILL arc matching checks neighboring tolerance cells and exact coordinate deltas", "Quantized equality alone misses valid pairs" in overkill and "for dx in -1i64..=1" in overkill and "(center.x - other_center.x).abs() <= q" in overkill)
check("OVERKILL has a regression for arcs straddling a spatial bucket boundary", "arcs_within_tolerance_across_spatial_bucket_boundary_are_merged" in overkill_tests)
check("OVERKILL direction buckets are cyclic across the normalization seam", "normalized angle interval is cyclic" in overkill and "wrapped_records.extend" in overkill)
check("OVERKILL flips wrapped line axes before collinear projection", "r.u = r.u * -1.0" in overkill and "collinear_lines_merge_across_direction_normalization_seam" in overkill_tests)
fillet_curves = (ROOT / "source/cadcraft/crates/engine/src/cmd/modify2/fillet.rs").read_text()
curve_edits = (ROOT / "source/cadcraft/crates/engine/src/cmd/modify2/curve_edits.rs").read_text()
fillet_geom = (ROOT / "source/cadcraft/crates/geom/src/fillet.rs").read_text()
check("Line/arc/circle FILLET routes through the shared tolerance-aware solver", "curve_edits::fillet_curvy(s, h1, p1, h2, p2, r, &e1, &e2)" in fillet_curves and "tangent_circles_with_tolerance" in curve_edits)
check("FILLET no longer rejects finite nonzero lines using a fixed 1e-12 length cutoff", "ln.len() > 0.0" in curve_edits and "ln.len() > 1e-12" not in curve_edits)
check("Microscopic line FILLET has a scale-aware geometry regression", "tolerance_aware_line_fillet_preserves_microscopic_radius" in fillet_geom)
workflow = (ROOT / ".github/workflows/build.yml").read_text()
check("Android CI pins the Rust compiler to the workspace minimum version", "toolchain: 1.95.0" in workflow)
check("Android CI compiles every CADCraft workspace target before regression tests", "cargo check --locked --workspace --all-targets" in workflow)

for label, ok in checks:
    print(("PASS" if ok else "FAIL") + " - " + label)
print(f"\n{sum(ok for _, ok in checks)}/{len(checks)} critical-gap source checks passed.")
if not all(ok for _, ok in checks):
    raise SystemExit(1)
